import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.RycU2wFZ.js";const i="/docs/assets/arbiscan-phase1-tx.CBOQAN6F.png",m=JSON.parse('{"title":"10-Minute Demo","description":"Run three scenarios in a single command: normal payment success, over-budget rejection, and runaway loop tripped by circuit breaker.","frontmatter":{"title":"10-Minute Demo","description":"Run three scenarios in a single command: normal payment success, over-budget rejection, and runaway loop tripped by circuit breaker."},"headers":[],"relativePath":"learn/05-hands-on/ten-minute-demo.md","filePath":"learn/05-hands-on/ten-minute-demo.md","lastUpdated":1792490239000}'),o={name:"learn/05-hands-on/ten-minute-demo.md"};function r(l,e,d,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="_10-minute-demo" tabindex="-1">10-Minute Demo <a class="header-anchor" href="#_10-minute-demo" aria-label="Permalink to &quot;10-Minute Demo&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay has not undergone an independent security audit. Do not use with production funds. This walkthrough uses testnets and test tokens only.</p></div><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><p>A single demo script runs locally on your machine, walking sequentially through three real-world scenarios:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>What Happens</th><th>Firewall Response</th></tr></thead><tbody><tr><td><strong>1. Normal Payment</strong></td><td>Agent purchases an NVDA market quote priced at $0.05</td><td>Approved → Signed → Settled, agent receives data</td></tr><tr><td><strong>2. Over-Budget Attempt</strong></td><td>Agent calls a heavy computing endpoint priced at $2.50</td><td>Single cap is $0.10; rejected immediately, <strong>no signature generated</strong></td></tr><tr><td><strong>3. Runaway Loop</strong></td><td>Agent gets trapped in an infinite retry loop</td><td>Limit is 5 RPM; circuit breaker trips and blocks all subsequent calls</td></tr></tbody></table><p>The demo firewall is configured with:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Single Cap: $0.10  |  24-Hour Budget: $1.00  |  Max 5 Requests / Minute</span></span></code></pre></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Python 3.10+, <code>make</code>, and <code>git</code></li><li>Clone the repository:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/july-whj/AgentPay.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AgentPay</span></span></code></pre></div><ul><li>Refer to the repository README for dependency installation.</li></ul><h2 id="step-1-run-in-memory-simulation-recommended-first" tabindex="-1">Step 1: Run In-Memory Simulation (Recommended First) <a class="header-anchor" href="#step-1-run-in-memory-simulation-recommended-first" aria-label="Permalink to &quot;Step 1: Run In-Memory Simulation (Recommended First)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span></span></code></pre></div><p>This mode simulates the complete payment chain in memory—<strong>no network calls, zero gas spent, no test tokens required</strong>. It completes in seconds with 100% deterministic results.</p><h3 id="phase-1-normal-micro-payment" tabindex="-1">Phase 1: Normal Micro-Payment <a class="header-anchor" href="#phase-1-normal-micro-payment" aria-label="Permalink to &quot;Phase 1: Normal Micro-Payment&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; [PHASE 1] Normal Micro-Payment with On-Chain Settlement &lt;&lt;&lt;</span></span>
<span class="line"><span>Agent requests paid market data for &#39;NVDA&#39; ($0.05 USDC).</span></span>
<span class="line"><span>✓ Tool Response Received: {&#39;ticker&#39;: &#39;NVDA&#39;, &#39;price&#39;: 142.5, ...}</span></span>
<span class="line"><span>[Facilitator] ON_CHAIN_TRANSACTION_CONFIRMED</span></span></code></pre></div><p>The agent executed a standard tool call, while under the hood:</p><ol><li>Upstream returned an HTTP 402 &quot;Payment Required&quot; challenge.</li><li>The firewall evaluated: $0.05 is within single cap, budget available → <strong>Approved</strong>.</li><li>Local signer generated an off-chain authorization transfer signature.</li><li>Client retried with the payment header and received data.</li><li>The facilitator submitted the authorization for settlement.</li></ol><p>Notice this line in the log:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;gasChargedToBuyer&quot;: &quot;0.0000 ETH (Free EIP-3009 Transfer)&quot;</span></span></code></pre></div><p>The buyer&#39;s wallet only holds USDC; it does not need ETH for gas (see <a href="./../02-agent-payments/gasless-eip-3009">Gasless Auth (EIP-3009)</a>).</p><h3 id="phase-2-exceeding-single-transaction-cap" tabindex="-1">Phase 2: Exceeding Single-Transaction Cap <a class="header-anchor" href="#phase-2-exceeding-single-transaction-cap" aria-label="Permalink to &quot;Phase 2: Exceeding Single-Transaction Cap&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[BuyerFirewall] POLICY_VIOLATION_INTERCEPTED</span></span>
<span class="line"><span>  &quot;errorCode&quot;: &quot;SINGLE_TX_CAP_EXCEEDED&quot;,</span></span>
<span class="line"><span>  &quot;requestedAmountUsdc&quot;: &quot;2.50&quot;,</span></span>
<span class="line"><span>  &quot;maxAllowedPerTxUsdc&quot;: &quot;0.10&quot;,</span></span>
<span class="line"><span>  &quot;action&quot;: &quot;PAYMENT_ABORTED_SAFELY&quot;,</span></span>
<span class="line"><span>  &quot;walletFundsDrained&quot;: &quot;0.00 USDC&quot;</span></span></code></pre></div><p>The endpoint asked for $2.50, but the single cap is $0.10. The firewall rejected the request <strong>before reaching the signer</strong>. With no signature generated, zero funds can leave the wallet.</p><p>Notice the <code>toolObservation</code> line in the log: the rejection reason is returned directly to the agent. The agent understands <em>why</em> it was blocked and can choose an alternative strategy, but has no mechanism to bypass or modify the policy.</p><h3 id="phase-3-runaway-loop-intercepted-by-circuit-breaker" tabindex="-1">Phase 3: Runaway Loop Intercepted by Circuit Breaker <a class="header-anchor" href="#phase-3-runaway-loop-intercepted-by-circuit-breaker" aria-label="Permalink to &quot;Phase 3: Runaway Loop Intercepted by Circuit Breaker&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[BuyerFirewall] CIRCUIT_BREAKER_TRIPPED</span></span>
<span class="line"><span>  &quot;iteration&quot;: 5,</span></span>
<span class="line"><span>  &quot;breakerState&quot;: &quot;OPEN&quot;,</span></span>
<span class="line"><span>  &quot;reason&quot;: &quot;CIRCUIT_MAX_RPM_EXCEEDED (Max 5 RPM exceeded)&quot;,</span></span>
<span class="line"><span>  &quot;cooldownSeconds&quot;: 300</span></span>
<span class="line"><span>✗ Loop iteration #5 BLOCKED by Circuit Breaker</span></span></code></pre></div><p>The agent enters a runaway loop, firing 8 rapid invocations. The first 4 succeeded; combined with Phase 1, 5 payments occurred within one minute. On iteration 5, the circuit breaker tripped to <code>OPEN</code>, immediately blocking all subsequent invocations with a 300-second cooldown.</p><p>This is how the &quot;$1,800/hour runaway loop&quot; described in <a href="./../04-agentpay-concepts/financial-firewall">Why We Need a Financial Firewall</a> is halted in seconds.</p><h3 id="final-audit-summary" tabindex="-1">Final Audit Summary <a class="header-anchor" href="#final-audit-summary" aria-label="Permalink to &quot;Final Audit Summary&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Calls Attempted:             10</span></span>
<span class="line"><span>Successful Paid Calls:       5</span></span>
<span class="line"><span>Over-Budget Blocks:          1</span></span>
<span class="line"><span>Runaway Loop Blocks:         4</span></span>
<span class="line"><span>Total Spend Attempted:       $2.63 USDC</span></span>
<span class="line"><span>Actual Funds Debited:        $0.09 USDC</span></span>
<span class="line"><span>Total Funds Saved by AgentPay: $2.54 USDC</span></span></code></pre></div><p>Reconciling the numbers:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Details</th></tr></thead><tbody><tr><td>10 calls attempted</td><td>Phase 1 (1) + Phase 2 (1) + Phase 3 (8)</td></tr><tr><td>5 successful paid calls</td><td>Phase 1 (1) + First 4 loop iterations</td></tr><tr><td>5 blocked calls</td><td>Over-cap (1) + Circuit breaker (4)</td></tr><tr><td>Actual debited: $0.09</td><td>Total of the 5 authorized micro-payments</td></tr><tr><td>Saved: $2.54</td><td>$2.50 over-cap call + 4 blocked loop iterations</td></tr></tbody></table><p>Important note: <strong>The 4 micro-payments executed before the circuit breaker tripped are non-refundable.</strong> The firewall caps maximum loss; it does not reduce authorized spending to zero.</p><h2 id="step-2-optional-real-on-chain-settlement" tabindex="-1">Step 2 (Optional): Real On-Chain Settlement <a class="header-anchor" href="#step-2-optional-real-on-chain-settlement" aria-label="Permalink to &quot;Step 2 (Optional): Real On-Chain Settlement&quot;">​</a></h2><p>To see transactions broadcast and confirmed on a public blockchain explorer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo-live</span></span></code></pre></div><p>This mode broadcasts genuine transactions to the Arbitrum Sepolia testnet.</p><h3 id="additional-prerequisites" tabindex="-1">Additional Prerequisites <a class="header-anchor" href="#additional-prerequisites" aria-label="Permalink to &quot;Additional Prerequisites&quot;">​</a></h3><ul><li><strong>Facilitator wallet</strong>: Funded with a small amount of Arbitrum Sepolia testnet ETH for gas.</li><li><strong>Buyer wallet</strong>: Funded with Circle testnet USDC.</li><li>Configure private keys and RPC in your environment according to README instructions.</li></ul><div class="danger custom-block"><p class="custom-block-title">Do Not Use Public Keys</p><p>Many public tutorials and local dev frameworks embed publicly known private keys. Bots constantly monitor those addresses. Always generate <strong>brand-new test keys</strong> for live mode and fund only with testnet faucet tokens. Never use test keys on mainnet.</p></div><h3 id="verify-on-arbiscan" tabindex="-1">Verify on Arbiscan <a class="header-anchor" href="#verify-on-arbiscan" aria-label="Permalink to &quot;Verify on Arbiscan&quot;">​</a></h3><p>Upon completion, Phase 1 outputs a transaction hash and Arbiscan explorer link:</p><p><img src="`+i+`" alt="Phase 1 Transaction on Arbiscan"></p><p>How to interpret the explorer fields:</p><table tabindex="0"><thead><tr><th>Arbiscan Field</th><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Status</strong></td><td>Success</td><td>Transaction executed successfully on-chain</td></tr><tr><td><strong>ERC-20 Tokens Transferred</strong></td><td>0.05 USDC from buyer to seller</td><td>Actual amount spent, matching demo logs</td></tr><tr><td><strong>From</strong></td><td>Facilitator wallet address</td><td>Transaction broadcast and <strong>gas paid by Facilitator, not Buyer</strong></td></tr><tr><td><strong>Transaction Fee</strong></td><td>~0.0000018 ETH</td><td>Gas absorbed by the facilitator; 0 ETH for buyer</td></tr><tr><td><strong>Value</strong></td><td>0 ETH</td><td>Native ETH transferred is zero; only USDC moved</td></tr><tr><td><strong>Timestamp</strong></td><td>Matches terminal log</td><td>Real-time on-chain confirmation</td></tr></tbody></table><p>This confirms the zero-gas model: the buyer authorizes the transfer with an off-chain signature, while the facilitator broadcasts the transaction and pays the network gas fee.</p><details class="details custom-block"><summary>Live Mode Notice: &quot;nonce too low&quot;</summary><p>During live mode settlement, you may occasionally observe:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Failed to broadcast settlement tx: RPC error -32000: nonce too low ...</span></span>
<span class="line"><span>Settlement submission failed ... Facilitator error 409: Nonce has already been submitted for settlement</span></span></code></pre></div><p><code>nonce too low</code> indicates that the facilitator transaction nonce was preempted on-chain. This happens when the same wallet broadcasts multiple transactions concurrently or the address is used by multiple processes.</p><p>In such cases, affected settlements await reconciliation rather than immediate broadcast, illustrating <a href="./../04-agentpay-concepts/timeout-is-not-failure">Timeout Is Not Failure</a>: <strong>&quot;Submission failure&quot; does not mean &quot;transaction does not exist&quot;; state must be verified prior to re-transmission.</strong></p></details><h2 id="verification-checklist" tabindex="-1">Verification Checklist <a class="header-anchor" href="#verification-checklist" aria-label="Permalink to &quot;Verification Checklist&quot;">​</a></h2><p>After running the demo, verify that:</p><ul><li>[ ] Phase 1: Market data returned; buyer gas charged is 0</li><li>[ ] Phase 2: Intercepted with <code>SINGLE_TX_CAP_EXCEEDED</code>; zero funds left wallet</li><li>[ ] Phase 3: Blocked on iteration 5 with circuit breaker state <code>OPEN</code></li><li>[ ] Audit summary: Total funds saved exceeds actual debited funds</li><li>[ ] (Live mode): Phase 1 transaction verified on Arbiscan</li></ul><h2 id="try-experimenting" tabindex="-1">Try Experimenting <a class="header-anchor" href="#try-experimenting" aria-label="Permalink to &quot;Try Experimenting&quot;">​</a></h2><p>Open <code>examples/runaway-agent/demo.py</code> and tweak the firewall parameters (single cap, 24-hour budget, max RPM):</p><ol><li>Increase single cap to $3.00 and re-run. Does Phase 2 still get blocked? If so, which rule triggers?</li><li>Increase max RPM to 20. At which iteration does the circuit breaker trip?</li><li>Reduce 24-hour budget to $0.05. How does Phase 3 behave?</li></ol><p>Observe the <code>errorCode</code> in terminal logs to see which policy rule intercepted each request.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Understand firewall architecture: <a href="./../04-agentpay-concepts/financial-firewall">Why We Need a Financial Firewall</a></li><li>Learn how concurrent budgets avoid overspending: <a href="./../04-agentpay-concepts/budget-reservation">Budget Reservation</a></li><li>Configure paid routes in Web Console: <a href="./first-paid-route">First Paid Route</a></li></ul>`,57)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
